# Comprehensive acceptance test script
DEV_GRAPH_ROOT="/Users/dm/orca/workspaces/HarnessHub/wt-13/eval-log/dev-graph/live-trial-fixtures/wt13-ci-schedule-20260730"
python3 - "$DEV_GRAPH_ROOT" <<'PYEOF'
import json, sys

root = sys.argv[1]
graph = json.load(open(f"{root}/.dev-graph/state/graph.json"))
leases = json.load(open(f"{root}/.git/dev-graph/leases.json"))
receipt = json.load(open(f"{root}/eval-log/run-dev-graph-schedule-execution.json"))

nodes = {n["graph_node_id"]: n for n in graph["nodes"]}
results = []

# OUT1: All ready tasks have all depends_on done
ready_tasks = receipt["ready_set"]["tasks"]
for tid in ready_tasks:
    node = nodes[tid]
    for dep in node["depends_on"]:
        dep_node = nodes.get(dep)
        if dep_node and dep_node["completion_evidence"]["status"] != "done":
            results.append(f"FAIL OUT1: {tid} has unmet dep {dep}")
if not any("FAIL OUT1" in r for r in results):
    results.append("PASS OUT1: all ready tasks have met dependencies")

# Verify blocked task LT-SCHED-005 excluded
if "LT-SCHED-005" not in ready_tasks:
    results.append("PASS: LT-SCHED-005 (blocked dep) excluded from ready set")
else:
    results.append("FAIL: LT-SCHED-005 should be excluded (unmet dep on LT-SCHED-001)")

# Verify LT-SCHED-004 excluded (active lease)
if "LT-SCHED-004" not in ready_tasks:
    results.append("PASS: LT-SCHED-004 (active lease) excluded from ready set")
else:
    results.append("FAIL: LT-SCHED-004 should be excluded (active lease)")

# Verify LT-SCHED-006 included (stale lease reclaimed)
if "LT-SCHED-006" in ready_tasks:
    results.append("PASS: LT-SCHED-006 (stale lease) included in ready set")
else:
    results.append("FAIL: LT-SCHED-006 should be included (stale lease expired 2020)")

# OUT2: No resource_scope overlap within batches
for bi, batch in enumerate(receipt["batches"]["tasks"]):
    scopes = {}
    for tid in batch:
        for res in nodes[tid]["resource_scope"]:
            if res in scopes:
                results.append(f"FAIL OUT2: batch {bi} resource overlap {res}: {scopes[res]} vs {tid}")
            scopes[res] = tid
    if not any(f"FAIL OUT2: batch {bi}" in r for r in results):
        results.append(f"PASS OUT2: batch {bi} has no resource_scope overlap")

# Verify LT-SCHED-001 and LT-SCHED-002 in different batches
b1 = receipt["batches"]["tasks"][0]
b2 = receipt["batches"]["tasks"][1]
if ("LT-SCHED-001" in b1 and "LT-SCHED-002" in b2) or ("LT-SCHED-002" in b1 and "LT-SCHED-001" in b2):
    results.append("PASS: LT-SCHED-001 and LT-SCHED-002 (resource conflict) in different batches")
else:
    results.append("FAIL: LT-SCHED-001 and LT-SCHED-002 should be in different batches")

# Max parallel
for bi, batch in enumerate(receipt["batches"]["tasks"]):
    if len(batch) <= 2:
        results.append(f"PASS: batch {bi} respects max-parallel 2 (size={len(batch)})")
    else:
        results.append(f"FAIL: batch {bi} exceeds max-parallel 2 (size={len(batch)})")

# Feature/task separation
if len(receipt["batches"]["features"]) == 0 and len(receipt["ready_set"]["features"]) == 0:
    results.append("PASS: feature and task ready-sets are separated (no features in this fixture)")

# OUT3: Unique branches and claim commands
branches = set()
claims = set()
for hint in receipt["assignment_hints"]:
    b = hint["suggested_branch"]
    c = hint["claim_command"]
    nid = hint["graph_node_id"]
    if b in branches:
        results.append(f"FAIL OUT3: duplicate branch {b}")
    branches.add(b)
    if not b.startswith("devgraph/"):
        results.append(f"FAIL OUT3: branch {b} doesn't start with devgraph/")
    if c in claims:
        results.append(f"FAIL OUT3: duplicate claim {c}")
    claims.add(c)
if not any("FAIL OUT3" in r for r in results):
    results.append("PASS OUT3: unique branches and claim commands per task")

# Digest immutability
if receipt["graph_sha256_before"] == receipt["graph_sha256_after"]:
    results.append("PASS: graph digest unchanged")
else:
    results.append("FAIL: graph digest changed")
if receipt["lease_sha256_before"] == receipt["lease_sha256_after"]:
    results.append("PASS: lease digest unchanged")
else:
    results.append("FAIL: lease digest changed")

# Lease source
if receipt["lease_source"] == "git_common_dir":
    results.append("PASS: lease path is git common-dir")
else:
    results.append(f"FAIL: lease_source is {receipt['lease_source']}, expected git_common_dir")

# Read-only
if receipt["read_only"]:
    results.append("PASS: read_only=true")
else:
    results.append("FAIL: read_only should be true")

# Print results
all_pass = all("PASS" in r for r in results)
for r in results:
    print(r)
print(f"\nOVERALL: {'PASS' if all_pass else 'FAIL'}")
PYEOF

